import itertools

def get_all_xyz():
    return list(itertools.product(range(10), repeat=3))

def get_responses(xyz, a, b, c):
    x, y, z = xyz
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

def solve():
    xyz_list = get_all_xyz()
    n = len(xyz_list)

    # To speed up, let's just pick a subset of (a, b, c)
    possible_abc = list(itertools.product(range(10), repeat=3))

    # Try non-adaptive: 2 questions
    # This might be too slow. Let's try to see if 2 questions can work.
    # We can't try all pairs of (a,b,c). Let's try to find if there are any two (a,b,c)
    # that partition the space.
    # Actually, let's check if 2 questions can work by trying some random (a,b,c) pairs.

    import random
    random.seed(42)

    for _ in range(1000):
        abc1 = random.choice(possible_abc)
        abc2 = random.choice(possible_abc)

        responses = {}
        possible = True
        for xyz in xyz_list:
            r = (get_responses(xyz, *abc1), get_responses(xyz, *abc2))
            if r in responses:
                possible = False
                break
            responses[r] = xyz

        if possible:
            return "2 questions (non-adaptive) might work with: " + str(abc1) + ", " + str(abc2)

    return "2 questions (non-adaptive) might not work with random sampling"

print(solve())

