import itertools

def get_all_xyz():
    return list(itertools.product(range(10), repeat=3))

def get_responses(xyz, a, b, c):
    x, y, z = xyz
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

def solve_better_greedy():
    xyz_list = get_all_xyz()
    possible_abc = list(itertools.product(range(10), repeat=3))

    responses_table = []
    for abc in possible_abc:
        r_list = []
        for xyz in xyz_list:
            r_list.append(get_responses(xyz, *abc))
        responses_table.append(r_list)

    # Step 1
    best_abc1 = -1
    min_max_size1 = 1001
    for abc_idx in range(1000):
        counts = {}
        for xyz_idx in range(1000):
            r = responses_table[abc_idx][xyz_idx]
            counts[r] = counts.get(r, 0) + 1
        max_size = max(counts.values())
        if max_size < min_max_size1:
            min_max_size1 = max_size
            best_abc1 = abc_idx

    print(f"Step 1: max_size = {min_max_size1}")

    # Step 2
    # We need to find the best abc2 given the best abc1
    # But there might be multiple best abc1. Let's just pick one.
    groups = {}
    for xyz_idx in range(1000):
        r = responses_table[best_abc1][xyz_idx]
        if r not in groups:
            groups[r] = []
        groups[r].append(xyz_idx)

    best_abc2 = -1
    min_max_size2 = 1001
    for abc_idx in range(1000):
        # For this abc_idx, the new groups will be (r1, r2)
        # We want to minimize the max size of these new groups
        new_group_counts = {}
        for r1, group in groups.items():
            for xyz_idx in group:
                r2 = responses_table[abc_idx][xyz_idx]
                new_group_counts[(r1, r2)] = new_group_counts.get((r1, r2), 0) + 1
        max_size = max(new_group_counts.values())
        if max_size < min_max_size2:
            min_max_size2 = max_size
            best_abc2 = abc_idx

    print(f"Step 2: max_size = {min_max_size2}")

    # Step 3
    groups = {}
    for r1, group in groups.items():
        for xyz_idx in group:
            r2 = responses_table[best_abc2][xyz_idx]
            if (r1, r2) not in groups:
                groups[(r1, r2)] = []
            groups[(r1, r2)].append(xyz_idx)

    best_abc3 = -1
    min_max_size3 = 1001
    for abc_idx in range(1000):
        new_group_counts = {}
        for (r1, r2), group in groups.items():
            for xyz_idx in group:
                r3 = responses_table[abc_idx][xyz_idx]
                new_group_counts[(r1, r2, r3)] = new_group_counts.get((r1, r2, r3), 0) + 1
        max_size = max(new_group_counts.values())
        if max_size < min_max_size3:
            min_max_size3 = max_size
            best_abc3 = abc_idx

    print(f"Step 3: max_size = {min_max_size3}")
    return min_max_size3

print(solve_better_greedy())
